from scipy.optimize import least_squares
y=dP_dt
def nm(f): return np.mean(f**2)/np.var(y)
fams={
 'rat2_1':lambda p: (p[0]+p[1]*P+p[2]*P**2)/(1+p[3]*P),
 'rat3_1':lambda p: (p[0]+p[1]*P+p[2]*P**2+p[4]*P**3)/(1+p[3]*P),
 'exp_poly':lambda p: p[0]*np.exp(-p[1]*P)+p[2]+p[3]*P,
 'cubic_exp':lambda p: p[0]+p[1]*P+p[2]*P**2+p[3]*P**3+p[4]*np.exp(-p[5]*P),
 'logis_harv':lambda p: p[0]*P*(1-P/p[1])-p[2]*P**2/(p[3]+P**2)+p[4],
 'quad_hol':lambda p: p[0]+p[1]*P+p[2]*P**2 - p[3]*P**2/(1+p[4]*P),
}
for k,f in fams.items():
    bestv=None
    for s in range(12):
        p0=np.random.RandomState(s).uniform(-2,2,6)
        try:
            r=least_squares(lambda p: f(p)-y,p0)
            v=nm(r.fun)
            if bestv is None or v<bestv[0]: bestv=(v,np.round(r.x,4))
        except Exception as e: pass
